\begin{exercise}
\label{prob:2-4}


2-4. Show that the inclusion map ${\overline{\mathbb{B}}}^{n} \hookrightarrow  {\mathbb{R}}^{n}$ is smooth when ${\overline{\mathbb{B}}}^{n}$ is regarded as a smooth manifold with boundary.
\end{exercise}

